"""Uniform mixing obstruction when both lepton bases are generated by the same shell interpolation."""
from pathlib import Path
from runpy import run_path
from flint import arb,arb_mat

m=run_path(str(Path(__file__).with_name("ch39-shell-four-seesaw.py")))
eye=m["eye"]
d=arb_mat([[1],[1],[1]])/arb(3).sqrt()
P=eye-d*d.transpose()
for n in (25,255,719):
    H=sum(m["matrices"](n),arb_mat(3,3))/4
    B=P*H*P
    tr=sum(B[i,i] for i in range(3))
    B2=B*B
    disc2=2*sum(B2[i,i] for i in range(3))-tr*tr
    delta=disc2.sqrt()
    lo,hi=(tr-delta)/2,(tr+delta)/2
    diag=(d.transpose()*H*d)[0,0]
    assert diag>tr/2
    g=P*H*d
    h2=(g.transpose()*g)[0,0]
    hBh=(g.transpose()*B*g)[0,0]
    g1=((hi*h2-hBh)/delta).sqrt()
    g2=((hBh-lo*h2)/delta).sqrt()
    gap=min(hi.lower(),diag.lower())-g2-lo
    assert gap>0
    t=g1/gap
    overlap=((1-t*t)/(1+t*t))**2
    assert t<1 and overlap>arb(".90")
    deficit=((arb(3).sqrt()/2).acos()-2*t.atan())*180/arb.pi()
    print("zero",n,"uniform max PMNS element squared lower",overlap.str(14),
          "basis rotation deficit in degrees",deficit.str(12))
